import assert from 'node:assert/strict';
import {readFileSync,writeFileSync} from 'node:fs';
import {gunzipSync,gzipSync} from 'node:zlib';
import {createHash} from 'node:crypto';
import {loadCases,caseSpec} from '../../benchmark/v4/model.ts';
import {evaluateTrack,summarize} from '../../benchmark/v4/evaluator.ts';
import {verifyFrozen} from '../../benchmark/v4/contract.ts';
import {compileArcMotion} from '../../scripts/v0/optimizer/arc_motion.ts';
import {connectedArcOptions} from '../../scripts/v0/optimizer/connected_arcs.ts';
const out='generated/compiler-work-attribution-20260911',root='generated/compiler-design-audit-20260911';
const sha=b=>createHash('sha256').update(b).digest('hex');
function read(path){const b=readFileSync(path);assert.equal(sha(b),readFileSync(path+'.sha256','utf8').trim());return JSON.parse(path.endsWith('.gz')?gunzipSync(b).toString():b.toString());}
function write(path,value){const b=path.endsWith('.gz')?gzipSync(JSON.stringify(value)+'\n'):Buffer.from(JSON.stringify(value,null,2)+'\n');writeFileSync(path,b);writeFileSync(path+'.sha256',sha(b)+'\n');}
const run=read(root+'/memory-study/run.json.gz'),cases=loadCases(),plan=read(root+'/final-canonical/plan.json');
assert.deepEqual(verifyFrozen(),run.plan.judge);
for(const [p,digest] of Object.entries(plan.compiler.files))assert.equal(sha(readFileSync(p)),digest,p);
const rows=structuredClone(run.rows),replays=[];
let model;
for(const row of rows){
 const proof=row.policyPreviewStats;
 assert.equal(proof.totalFrames,proof.previewFrames+proof.searchFrames);
 assert.equal(row.attempts[0].end,proof.previewFrames);assert.equal(row.attempts[1].end-row.attempts[1].start,proof.searchFrames);
 if(!proof.previewComplete)continue;
 row.resources.physicalFrames=proof.previewFrames;
 if(proof.selected==='preview'){
  assert.equal(row.trackHash,row.attempts[0].trackHash);
  continue;
 }
 const c=cases.find(c=>c.id===row.sourceId),spec=caseSpec(c),options=connectedArcOptions(spec,run.plan.budget);
 model??=options.controlPolicy();
 const actual=compileArcMotion(spec,run.plan.seed,{...options,budget:Math.floor(options.budget*.05),controlPolicy:model.rolloutPolicy,
  policyPreview:false,policyRollout:true,policyRolloutStrict:true,lookaheadWidth:0,qualityRetries:0,refineAttempts:0,collectTrajectoryLoss:true});
 const trackHash=sha(JSON.stringify(actual.track));
 assert.equal(trackHash,row.attempts[0].trackHash,row.sourceId);assert.equal(actual.stats.sim_frames,proof.previewFrames);assert.equal(actual.trajectoryLoss,proof.previewLoss);
 const graded=evaluateTrack(c,actual.track);assert.equal(graded.score.valid,true);
 write(out+'/'+row.sourceId+'.json.gz',{track:actual.track,report:actual.report,stats:actual.stats,trackHash,...graded});
 replays.push({sourceId:row.sourceId,trackHash,physicsFrames:actual.stats.sim_frames,previousScore:row.score.score,previewScore:graded.score.score});
 Object.assign(row,graded,{trackHash});
 console.log(JSON.stringify(replays.at(-1)));
}
const before=summarize(run.rows,cases,[16]),after=summarize(rows,cases,[16]);
assert.deepEqual(before,run.summary);
const total=run.rows.reduce((s,r)=>s+r.resources.physicalFrames,0),remaining=rows.reduce((s,r)=>s+r.resources.physicalFrames,0);
const findings={schema:'line.compiler-work-counterfactual.v1',note:'Retrospective full 176-case seed-16 counterfactual, not a newly deployed compiler or wall-clock benchmark. Reuses the already measured successful preview outputs and five unchanged fallback outcomes; freshly cold-grades the three preview tracks previously displaced by successful search. No scorer changes.',compiler:plan.compiler,judge:run.plan.judge,sourceRunSha256:sha(readFileSync(root+'/memory-study/run.json.gz')),verificationScriptSha256:sha(readFileSync(import.meta.filename)),before,after,totalPhysicsFrames:total,counterfactualPhysicsFrames:remaining,reductionFraction:1-remaining/total,physicalWorkRatio:total/remaining,previewComplete:run.rows.filter(r=>r.policyPreviewStats.previewComplete).length,generalFallbacks:run.rows.filter(r=>!r.policyPreviewStats.previewComplete).length,replays,rows:rows.map(r=>({sourceId:r.sourceId,seed:r.seed,score:r.score,trackHash:r.trackHash,resources:r.resources}))};
write(out+'/result.json',findings);
console.log(JSON.stringify({before:before.headline,after:after.headline,valid:after.valid,totalPhysicsFrames:total,counterfactualPhysicsFrames:remaining,reductionPercent:100*findings.reductionFraction,physicalWorkRatio:findings.physicalWorkRatio}));
